create table if not exists public.creator_memory_access_requests (id uuid primary key default gen_random_uuid(), package_id uuid not null, requester_id uuid not null, purpose text not null, requested_fields jsonb not null, state text not null default 'draft', decision_reason text, expires_at timestamptz, idempotency_key text not null unique, created_at timestamptz not null default now());
create table if not exists public.creator_memory_reuse_permissions (id uuid primary key default gen_random_uuid(), package_id uuid not null, reuse_type text not null, exact_scope jsonb not null, recipient_id uuid, state text not null default 'draft', effective_at timestamptz, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.creator_memory_repatriation_cases (id uuid primary key default gen_random_uuid(), package_id uuid not null, requester_authority_id uuid not null, requested_remedy text not null, state text not null default 'draft', evidence_manifest_id uuid, decision_id uuid, created_at timestamptz not null default now());
create table if not exists public.creator_memory_remediation_actions (id uuid primary key default gen_random_uuid(), source_type text not null, source_id uuid not null, action_type text not null, prior_projection jsonb, replacement_projection jsonb, state text not null default 'proposed', created_at timestamptz not null default now());
alter table public.creator_memory_access_requests enable row level security; alter table public.creator_memory_reuse_permissions enable row level security; alter table public.creator_memory_repatriation_cases enable row level security; alter table public.creator_memory_remediation_actions enable row level security;
